const DATA={good:{tasks:[{task_id:'T001',title:'完成一次训练',reward_id:'R001',claim_limit:'1'}],rewards:[{reward_id:'R001',item_id:'GOLD',amount:'100'}],items:[{item_id:'GOLD',name:'金币'},{item_id:'TICKET',name:'训练券'}]},bad:{tasks:[{task_id:'T001',title:'完成一次训练',reward_id:'R001',claim_limit:'1'}],rewards:[{reward_id:'R001',item_id:'GOLD',amount:'10'}],items:[{item_id:'GOLD',name:'金币'},{item_id:'TICKET',name:'训练券'}]}};
const REQUIRED={tasks:['task_id','title','reward_id','claim_limit'],rewards:['reward_id','item_id','amount'],items:['item_id','name']};
let original=clone(DATA.bad),working=clone(DATA.bad),issues=[],resolved=[],selected=new Set(),previewSource='working',game={done:false,claims:0,coins:0},lastFingerprint='';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function clone(v){return JSON.parse(JSON.stringify(v))}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fingerprint(d){return JSON.stringify(d)}
function loadSample(type){original=clone(DATA[type]);working=clone(DATA[type]);issues=[];resolved=[];selected.clear();lastFingerprint='';renderFiles();resetReview();resetGame();toast(type==='good'?'已加载正常示例':'已加载含错误的示例');}
function renderFiles(){const rows=[['tasks','任务表'],['rewards','奖励表'],['items','物品表']];$('#fileList').innerHTML=rows.map(([key,label])=>`<div class="file-row"><span class="file-icon">CSV</span><span class="file-info"><b>${label} · ${key}.csv</b><small>${working[key]?.length||0} 行 · ${REQUIRED[key].length} 个字段</small></span><span class="file-ok">✓</span></div>`).join('');}
function resetReview(){ $('#emptyReview').classList.remove('hidden');$('#reviewContent').classList.add('hidden');$('#reviewSubtitle').textContent='等待运行检查';$('#scoreBadge').className='score-badge neutral';$('#scoreBadge').textContent='—';updateFlow(1)}
function parseNeed(text){const amount=text.match(/(?:奖励|获得|发放)\s*(\d+)\s*(?:个)?金币/);const limit=text.match(/(?:限领|领取|最多领取|只能领取)\s*(\d+|一|二|三)\s*次/);const map={一:1,二:2,三:3};return{amount:amount?+amount[1]:null,limit:limit?(map[limit[1]]||+limit[1]):null,ambiguous:/一点|一些|适量|若干/.test(text)}}
function addIssue(o){issues.push({id:`i${issues.length+1}`,status:'open',...o})}
function duplicates(rows,key,file){const seen=new Set;rows.forEach((r,i)=>{if(seen.has(r[key]))addIssue({severity:'error',title:`${key} 重复`,location:`${file}.csv · 第 ${i+2} 行 · ${key}`,current:r[key],basis:'项目规则：ID 不可重复',fixable:false});seen.add(r[key])})}
function inspect(){issues=[];selected.clear();const need=parseNeed($('#requirement').value.trim());$('#requirementHint').classList.toggle('hidden',!need.ambiguous);$('#requirementHint').textContent=need.ambiguous?'需求中的奖励数量不明确，请填写具体金币数量后再生成修复。':'';
  for(const [file,fields] of Object.entries(REQUIRED)){if(!working[file]){addIssue({severity:'error',title:`缺少 ${file}.csv`,location:file+'.csv',current:'文件不存在',basis:'输入要求：三张配置表必须齐全',fixable:false});continue}const got=Object.keys(working[file][0]||{});fields.filter(f=>!got.includes(f)).forEach(f=>addIssue({severity:'error',title:`缺少必要字段 ${f}`,location:file+'.csv',current:'字段不存在',basis:`${file}.csv 结构要求`,fixable:false}))}
  if(working.tasks&&working.rewards&&working.items){duplicates(working.tasks,'task_id','tasks');duplicates(working.rewards,'reward_id','rewards');duplicates(working.items,'item_id','items');const rewardIds=new Set(working.rewards.map(x=>x.reward_id)),itemIds=new Set(working.items.map(x=>x.item_id));working.tasks.forEach((t,i)=>{if(!rewardIds.has(t.reward_id))addIssue({severity:'error',title:'任务引用的奖励不存在',location:`tasks.csv · ${t.task_id||'第'+(i+2)+'行'} · reward_id`,current:t.reward_id,basis:'项目规则：引用的奖励必须存在',fixable:false});if(t.title!=='完成一次训练')addIssue({severity:'error',title:'暂不支持该任务行为',location:`tasks.csv · ${t.task_id} · title`,current:t.title,basis:'第一版只支持“完成一次训练”',fixable:false});const lim=+t.claim_limit;if(!Number.isInteger(lim)||lim<1)addIssue({severity:'error',title:'领取次数必须为正整数',location:`tasks.csv · ${t.task_id} · claim_limit`,current:t.claim_limit,basis:'字段规则：领取次数为正整数',fixable:false});if(need.limit&&lim!==need.limit)addIssue({severity:'warning',title:'领取次数与需求不一致',location:`tasks.csv · ${t.task_id} · claim_limit`,current:t.claim_limit,next:String(need.limit),basis:`需求：“每个账号限领 ${need.limit} 次”`,fixable:true,file:'tasks',row:i,field:'claim_limit'})});working.rewards.forEach((r,i)=>{if(!itemIds.has(r.item_id))addIssue({severity:'error',title:'奖励引用的物品不存在',location:`rewards.csv · ${r.reward_id} · item_id`,current:r.item_id,basis:'项目规则：引用的物品必须存在',fixable:false});const n=Number(r.amount);if(!Number.isInteger(n)||n<=0)addIssue({severity:'error',title:'奖励数量不是正整数',location:`rewards.csv · ${r.reward_id} · amount`,current:r.amount,basis:'项目规则：奖励数量必须为正整数',fixable:false});if(r.item_id==='GOLD'&&n>500)addIssue({severity:'error',title:'金币奖励超过项目上限',location:`rewards.csv · ${r.reward_id} · amount`,current:r.amount,basis:'项目规则：单任务金币奖励不超过 500',fixable:false});if(r.item_id==='GOLD'&&need.amount&&!need.ambiguous&&n!==need.amount){addIssue({severity:need.amount>500?'error':'warning',title:need.amount>500?'需求与项目规则冲突':'奖励数量与需求不一致',location:`rewards.csv · ${r.reward_id} · amount`,current:r.amount,next:String(need.amount),basis:need.amount>500?'需求数量超过项目上限 500，需要人工确认':'需求：“奖励 '+need.amount+' 金币”',fixable:need.amount<=500,file:'rewards',row:i,field:'amount'})}})}
  lastFingerprint=fingerprint(working);renderIssues();updatePreview();updateFlow(2);}
function renderIssues(filter='all'){const open=issues.filter(i=>i.status==='open'),errs=open.filter(i=>i.severity==='error').length,warns=open.filter(i=>i.severity==='warning').length;$('#emptyReview').classList.add('hidden');$('#reviewContent').classList.remove('hidden');$('#reviewSubtitle').textContent=open.length?`发现 ${open.length} 个待处理问题`:'全部检查已通过';$('#scoreBadge').className='score-badge '+(open.length?'bad':'good');$('#scoreBadge').textContent=open.length?`${open.length} 项`:'通过';$('#summaryRow').innerHTML=`<div class="summary-card"><b style="color:var(--red)">${errs}</b><span>阻断问题</span></div><div class="summary-card"><b style="color:var(--amber)">${warns}</b><span>可确认修复</span></div><div class="summary-card"><b style="color:var(--green)">${resolved.length}</b><span>已解决</span></div>`;let list=[...issues,...resolved];if(filter==='resolved')list=resolved;else if(filter!=='all')list=issues.filter(i=>i.severity===filter&&i.status==='open');$('#issueList').innerHTML=list.length?list.map(issueHTML).join(''):`<div class="empty-state" style="min-height:260px"><h3>${open.length?'该分类暂无问题':'配置检查通过'}</h3><p>${open.length?'请选择其他筛选项':'可以进入右侧预览验证实际发奖结果。'}</p></div>`;bindChoices();$('#repairBar').classList.toggle('hidden',selected.size===0);$('#repairCount').textContent=selected.size;if(!open.length)updateFlow(4);}
function issueHTML(i){const done=i.status==='resolved';return `<article class="issue ${done?'resolved':i.severity}"><div class="issue-head"><span class="severity">${done?'✓':i.severity==='error'?'!':'↗'}</span><div class="issue-title"><b>${esc(i.title)}</b><small>${esc(i.location)}</small></div></div><div class="issue-body"><b>当前值：</b>${esc(i.current)}<br><b>依据：</b>${esc(i.basis)}${i.next!==undefined?`<div class="diff"><span>${esc(i.current)}</span><b>→</b><span>${esc(i.next)}</span></div>`:''}</div>${i.fixable&&!done?`<label class="repair-choice"><input type="checkbox" data-issue="${i.id}" ${selected.has(i.id)?'checked':''}> 生成这项修复并等待确认</label>`:`<small class="repair-choice">${done?'已在工作副本中解决':'仅报告 · 缺少唯一、可靠的修复依据'}</small>`}</article>`}
function bindChoices(){$$('#issueList input[data-issue]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.issue):selected.delete(el.dataset.issue);$('#repairBar').classList.toggle('hidden',!selected.size);$('#repairCount').textContent=selected.size})}
function applyRepairs(){if(fingerprint(working)!==lastFingerprint){toast('配置已改变，旧修复方案已失效');inspect();return}const done=[];issues.forEach(i=>{if(selected.has(i.id)&&i.fixable){working[i.file][i.row][i.field]=i.next;i.status='resolved';done.push(i)}});resolved.push(...done);selected.clear();toast(`已应用 ${done.length} 项修改，正在复检`);inspect();renderIssues();resetGame();updateFlow(3)}
function validPreview(data){const t=data.tasks?.[0],r=data.rewards?.find(x=>x.reward_id===t?.reward_id),it=data.items?.find(x=>x.item_id===r?.item_id);if(!t)return{error:'无法预览：任务表为空'};if(!r)return{error:`无法预览：奖励 ${t.reward_id} 不存在`};if(!it)return{error:`无法预览：物品 ${r.item_id} 不存在`};if(!Number.isInteger(+r.amount)||+r.amount<=0)return{error:'无法预览：奖励数量必须为正整数'};return{t,r,it}}
function updatePreview(){const data=previewSource==='working'?working:original,v=validPreview(data),err=$('#previewError');if(v.error){err.textContent=v.error;err.classList.remove('hidden');$('#completeBtn').disabled=true;$('#claimBtn').disabled=true;return}err.classList.add('hidden');$('#completeBtn').disabled=false;$('#previewTitle').textContent=v.t.title;$('#rewardAmount').textContent=v.r.amount;$('#limitText').textContent=`限领 ${v.t.claim_limit} 次`;$('#claimRecord').textContent=`${game.claims} / ${v.t.claim_limit}`;$('#coinBalance').textContent=game.coins;$('#sourceLabel').textContent=previewSource==='working'?'工作副本':'原始配置';$('#taskStatus').textContent=game.done?'已完成':'进行中';$('#taskStatus').classList.toggle('done',game.done);$('#completeBtn').textContent=game.done?'训练已完成':'完成训练';$('#completeBtn').disabled=game.done;$('#claimBtn').disabled=!game.done||game.claims>=+v.t.claim_limit;$('#claimBtn').textContent=game.claims>=+v.t.claim_limit?'已达领取上限':'领取奖励';}
function complete(){game.done=true;$('#gameMessage').textContent='训练完成，可以领取奖励';updatePreview()}
function claim(){const data=previewSource==='working'?working:original,v=validPreview(data);if(v.error)return;if(!game.done){$('#gameMessage').textContent='请先完成训练';return}if(game.claims>=+v.t.claim_limit){$('#gameMessage').textContent='已达到每账号领取上限';return}game.claims++;game.coins+=+v.r.amount;$('#gameMessage').textContent=`领取成功，获得 ${v.r.amount} ${v.it.name}`;updatePreview()}
function resetGame(){game={done:false,claims:0,coins:0};$('#gameMessage').textContent='请先完成训练';updatePreview()}
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean),headers=splitLine(lines.shift()||'');return lines.map(line=>Object.fromEntries(headers.map((h,i)=>[h.trim(),(splitLine(line)[i]||'').trim()]))) }
function splitLine(line){let out=[],cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===','&&!q){out.push(cur);cur=''}else cur+=c}out.push(cur);return out}
async function upload(files){const next=clone(working);for(const f of files){const key=['tasks','rewards','items'].find(k=>f.name.toLowerCase()===k+'.csv');if(!key){toast(`忽略无法识别的文件：${f.name}`);continue}try{next[key]=parseCSV(await f.text())}catch(e){toast(`${f.name} 无法解析`);return}}original=clone(next);working=clone(next);issues=[];resolved=[];renderFiles();resetReview();resetGame();toast('配置文件已载入')}
function exportAll(){const payload={requirement:$('#requirement').value,checked_at:new Date().toISOString(),status:issues.filter(i=>i.status==='open').length?'needs_attention':'passed',issues,configuration:working,changes:resolved.map(i=>({location:i.location,before:i.current,after:i.next,basis:i.basis}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='config-check-result.json';a.click();URL.revokeObjectURL(a.href);toast('检查结果已导出')}
function updateFlow(step){$$('.flow-item').forEach((el,i)=>el.classList.toggle('active',i<step))}function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2200)}
$('#loadGood').onclick=()=>loadSample('good');$('#loadBad').onclick=()=>loadSample('bad');$('#checkBtn').onclick=inspect;$('#applyBtn').onclick=applyRepairs;$('#fileInput').onchange=e=>upload([...e.target.files]);$('#completeBtn').onclick=complete;$('#claimBtn').onclick=claim;$('#resetBtn').onclick=resetGame;$('#exportBtn').onclick=exportAll;$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();$('#toggleRules').onclick=()=>toast('当前规则已全部展示');
$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderIssues(b.dataset.filter)});$$('.config-switch button').forEach(b=>b.onclick=()=>{$$('.config-switch button').forEach(x=>x.classList.remove('active'));b.classList.add('active');previewSource=b.dataset.source;resetGame()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')inspect()});$('#requirement').addEventListener('input',()=>{$('#saveState').textContent='● 有未检查的修改';lastFingerprint='stale'});
renderFiles();updatePreview();
